      "n": 1,
      "quote": "implements dense and hybrid search, indexing, deletion, navigation, and partial updates."
    },
    {
      "n": 2,
      "quote": "A backend can also expose partial updates without a full re-index by implementing the optional `PatchableIndex` protocol."
    }
  ],
  "insufficient_evidence": false
}

