  --header "Authorization: Bearer $(gcloud auth print-access-token)" \
  --data '{
      "model":"'"\$VERTEX_MODEL_NAME"'",
      "prompt": "def count_words_in_file(file_path: str) -> int:",
      "suffix": "return n_words",
      "stream": false
    }'
